"""The conformance campaigns a Kernarium automation run boots, as files.

A campaign is the guest launcher the macOS lanes run, generated by the same
driver for the image and page size the application will boot, beside its
systemd service and the session target every campaign boots
(``run_vk_gl_cts.cts_target``). A host driver writes these files into a boot
payload (tests/integration/support/kernarium.py), copies it into the
application's container and boots the target; the application itself carries
no campaign.
"""

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

from dataclasses import dataclass
import sys
from pathlib import Path
from typing import Any, Mapping

sys.path.insert(0, str(Path(__file__).resolve().parent))
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "support"))

import kernarium  # noqa: E402
import run_vk_cts as vulkan  # noqa: E402
import run_vk_gl_cts as cts  # noqa: E402


GL_DERIVATIVE_RECEIPT_PATH = Path(__file__).with_name(
    "vk_gl_cts_derivative_rootfs.json"
)
VULKAN_LAUNCHER_PATH = vulkan.CTS_SERVICE_PATH
VULKAN_WRAPPER_PATH = "/usr/local/libexec/uml-vulkan-cts-run"
VULKAN_SERVICE_NAME = vulkan.CTS_WSI_SERVICE_NAME
VULKAN_SERVICE_PATH = vulkan.CTS_WSI_SERVICE_PATH
VULKAN_SERVICE = """[Unit]
Description=Darwin UML Kernarium Vulkan CTS campaign
After=systemd-user-sessions.service
Wants=systemd-user-sessions.service

[Service]
Type=oneshot
ExecStart=/usr/local/libexec/uml-vulkan-cts-run
StandardInput=null
StandardOutput=journal+console
StandardError=journal+console
"""
# The development identity campaign passes with dEQP's no-device status, the
# baseline its identity records.
VULKAN_DEVELOPMENT_WRAPPER = """#!/bin/sh
set -eu
set +e
/usr/local/libexec/uml-vulkan-cts
status=$?
set -e
if [ "$status" -ne 137 ]; then
    echo "UML_VK_CTS_ERROR: expected no-device status 137, got $status"
    exit 1
fi
sync
systemctl poweroff --no-wall --no-block || kill -RTMIN+4 1
"""
VULKAN_RECEIPT_WRAPPER = """#!/bin/sh
set -eu
set +e
/usr/local/libexec/uml-vulkan-cts
status=$?
set -e
printf 'Kernarium Vulkan CTS campaign exited with status %s\\n' "$status"
sync
systemctl poweroff --no-wall --no-block || kill -RTMIN+4 1
"""


@dataclass(frozen=True)
class Campaign:
    """One campaign's guest files, by guest path, and the target it boots."""

    identifier: str
    files: Mapping[str, tuple[bytes, int]]
    unit: str = cts.CTS_TARGET_UNIT

    def payload(self) -> kernarium.Payload:
        payload = kernarium.Payload()
        for guest_path, (contents, mode) in sorted(self.files.items()):
            payload.add(guest_path, contents, mode)
        return payload


def _gl_inputs() -> tuple[
    dict[str, Any],
    dict[str, cts.AppleCampaign],
    dict[str, cts.AppleMatrixShard],
]:
    identity = cts.load_identity()
    receipt, _ = cts.load_derivative_receipt(
        GL_DERIVATIVE_RECEIPT_PATH, identity
    )
    # The desktop GL matrix cell lives in the sealed derivative's receipt, so
    # the shards are expanded against it rather than the base identity.
    return (
        identity,
        cts.load_apple_campaigns(identity),
        cts.load_apple_matrix_shards(identity, receipt=receipt),
    )


def identifiers() -> tuple[str, ...]:
    """Every campaign, GL first, in the order the lanes list them."""
    _, campaigns, shards = _gl_inputs()
    return (
        *campaigns,
        *shards,
        *(f"{api}-config-inventory-v1" for api in cts.BASELINE_GLES_APIS),
        *vulkan.apple_campaigns(),
    )


def gl_contract(identity: dict[str, Any], image_type: str) -> cts.RootfsContract:
    if image_type == "erofs":
        return cts.select_rootfs_contract(identity, "erofs", None)[1]
    return cts.select_rootfs_contract(
        identity, "ext4", GL_DERIVATIVE_RECEIPT_PATH
    )[1]


def _gl_campaign(identifier: str, launcher: str) -> Campaign:
    return Campaign(
        identifier,
        {
            cts.GUEST_LAUNCHER_PATH: (launcher.encode(), 0o755),
            cts.GUEST_SERVICE_PATH: (cts.CTS_SERVICE.encode(), 0o644),
            cts.CTS_TARGET_PATH: (
                cts.cts_target(cts.GUEST_SERVICE_NAME).encode(), 0o644
            ),
        },
    )


def _vulkan_campaign(
    identifier: str,
    launcher: str,
    wrapper: str,
    case_list: bytes | None,
) -> Campaign:
    files = {
        VULKAN_LAUNCHER_PATH: (launcher.encode(), 0o755),
        VULKAN_WRAPPER_PATH: (wrapper.encode(), 0o755),
        VULKAN_SERVICE_PATH: (VULKAN_SERVICE.encode(), 0o644),
        cts.CTS_TARGET_PATH: (
            cts.cts_target(VULKAN_SERVICE_NAME).encode(), 0o644
        ),
    }
    if case_list is not None:
        files[vulkan.GUEST_CASE_LIST_PATH] = (case_list, 0o644)
    return Campaign(identifier, files)


def _selected_cases(
    selection: vulkan.DevelopmentSelection | vulkan.ReceiptSelection,
) -> bytes:
    return "".join(f"{case}\n" for case in selection.source_cases).encode()


def build(identifier: str, *, image_type: str) -> Campaign:
    """The campaign ``identifier`` for an image of ``image_type``.

    Raises CampaignError for an unknown campaign or one the image cannot
    run: the official desktop GL matrix and the receipt-backed Vulkan
    campaigns are bound to sealed ext4 derivatives, and the development
    Vulkan identity to the frozen EROFS image.
    """
    if image_type not in ("erofs", "ext4"):
        raise cts.CampaignError("unsupported image type")
    if identifier in vulkan.apple_campaigns():
        return _build_vulkan(identifier, image_type)
    identity, campaigns, shards = _gl_inputs()
    contract = gl_contract(identity, image_type)
    campaign = campaigns.get(identifier)
    if campaign is not None:
        return _gl_campaign(
            identifier,
            cts.build_guest_launcher(
                campaign.selection,
                campaign.seed,
                campaign.shard_timeout,
                contract,
            ),
        )
    shard = shards.get(identifier)
    if shard is not None:
        if shard.api == "gl46" and image_type != "ext4":
            raise cts.CampaignError(
                "the official GL matrix requires the sealed ext4 derivative"
            )
        return _gl_campaign(
            identifier,
            cts.build_guest_launcher(
                shard.selection,
                shard.seed,
                shard.shard_timeout,
                contract,
                matrix=shard.matrix,
                renderer_backend=shard.renderer_backend,
            ),
        )
    for api in cts.BASELINE_GLES_APIS:
        if identifier == f"{api}-config-inventory-v1":
            return _gl_campaign(
                identifier,
                cts.build_guest_launcher(
                    None, 0, 900, contract,
                    config_inventory_api=api,
                ),
            )
    raise cts.CampaignError(f"no Kernarium campaign {identifier}")


def _build_vulkan(identifier: str, image_type: str) -> Campaign:
    if identifier == vulkan.APPLE_DEVELOPMENT_CAMPAIGN:
        if image_type != "erofs":
            raise cts.CampaignError(
                "the development Vulkan identity campaign requires the frozen "
                "EROFS image"
            )
        identity = vulkan.load_identity()
        selection = vulkan.resolve_selection(
            identity, "smoke", (), None, vulkan.Fraction(0, 1)
        )
        launcher = vulkan.build_guest_launcher(
            identity,
            selection,
            timeout=900,
            experimental_venus=True,
            case_list=vulkan.GUEST_CASE_LIST_PATH,
        )
        return _vulkan_campaign(
            identifier,
            launcher,
            VULKAN_DEVELOPMENT_WRAPPER,
            _selected_cases(selection),
        )
    if image_type != "ext4":
        raise cts.CampaignError(
            f"{identifier} requires the sealed Vulkan ext4 derivative"
        )
    receipt = vulkan.receipt_contract.validate_receipt(vulkan.RECEIPT_PATH)
    if identifier == vulkan.APPLE_RECEIPT_SMOKE_CAMPAIGN:
        selection = vulkan.resolve_receipt_selection(
            "smoke", (), None, vulkan.Fraction(0, 1)
        )
        options: dict[str, Any] = {"timeout": 900}
    else:
        index = next(
            index
            for index in range(vulkan.APPLE_MUSTPASS_FRACTIONS)
            if vulkan.apple_mustpass_campaign(index) == identifier
        )
        selection = vulkan.resolve_receipt_selection(
            "current-must-pass",
            (),
            None,
            vulkan.Fraction(index, vulkan.APPLE_MUSTPASS_FRACTIONS),
        )
        # A device campaign is the one lane whose guest memory is fixed by
        # the platform's jetsam budget, so only it applies the driver's
        # device-memory exclusions.
        options = {
            "timeout": vulkan.APPLE_MUSTPASS_TIMEOUT,
            "progress_timeout": vulkan.APPLE_MUSTPASS_PROGRESS_TIMEOUT,
            "device_exclusions": vulkan.DEVICE_EXCLUSIONS,
        }
    case_list = None
    if not selection.generated_expected:
        case_list = vulkan.GUEST_CASE_LIST_PATH
    launcher = vulkan.build_receipt_guest_launcher(
        receipt,
        selection,
        receipt_path=vulkan.RECEIPT_PATH,
        case_list=case_list,
        **options,
    )
    return _vulkan_campaign(
        identifier,
        launcher,
        VULKAN_RECEIPT_WRAPPER,
        _selected_cases(selection) if case_list is not None else None,
    )
